files.content:
:root {
  --bg: #1e1b2e;
  --card: #2a2740;
  --text: #f0eef8;
  --muted: #a9a5c4;
  --accent: #7c5cff;
  --accent-hover: #9a82ff;
  --bar-bg: #3d3a5c;
  --bar-fill: #7c5cff;
  --radius: 12px;
  --space: 16px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: var(--space);
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  padding: calc(var(--space) * 2);
  width: 100%;
  max-width: 520px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  line-height: 1.3;
  margin-bottom: calc(var(--space) * 0.5);
}

.subtitle {
  color: var(--muted);
  font-size: 1rem;
  margin-bottom: calc(var(--space) * 1.5);
}

.options {
  display: flex;
  flex-direction: column;
  gap: calc(var(--space) * 0.75);
  margin-bottom: calc(var(--space) * 1.5);
}

.option-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space);
  width: 100%;
  padding: calc(var(--space) * 0.75) var(--space);
  background: var(--bar-bg);
  color: var(--text);
  border: 2px solid transparent;
  border-radius: var(--radius);
  font-family: var(--font);
  font-size: 1rem;
  text-align: left;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}

.option-btn:hover {
  background: #4a4670;
}

.option-btn:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

.option-btn:active {
  transform: scale(0.98);
}

.option-btn[aria-pressed="true"] {
  border-color: var(--accent);
  background: #3a3560;
}

.option-label {
  font-weight: 600;
}

.option-count {
  font-size: 0.875rem;
  color: var(--muted);
  white-space: nowrap;
}

.results {
  display: flex;
  flex-direction: column;
  gap: calc(var(--space) * 0.75);
  margin-bottom: calc(var(--space) * 1.5);
}

.result-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.result-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.9375rem;
}

.result-label {
  font-weight: 600;
}

.result-pct {
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.bar-track {
  height: 10px;
  background: var(--bar-bg);
  border-radius: 999px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 0;
  background: var(--bar-fill);
  border-radius: 999px;
  transition: width 0.3s ease;
}

.reset-btn {
  width: 100%;
  padding: calc(var(--space) * 0.75) var(--space);
  background: transparent;
  color: var(--muted);
  border: 2px solid var(--bar-bg);
  border-radius: var(--radius);
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s, transform 0.1s;
}

.reset-btn:hover {
  background: var(--bar-bg);
  color: var(--text);
}

.reset-btn:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

.reset-btn:active {
  transform: scale(0.98);
}

@media (max-width: 400px) {
  .card {
    padding: var(--space);
  }
  h1 {
    font-size: 1.25rem;
  }
  .option-btn {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
  }
}

(function () {
  'use strict';

  var QUESTION = 'Which pixel art style do you prefer?';
  var OPTIONS = [
    { id: 'opt1', label: '8-bit Retro', initialVotes: 12 },
    { id: 'opt2', label: '16-bit Classic', initialVotes: 18 },
    { id: 'opt3', label: 'Modern Pixel', initialVotes: 9 },
    { id: 'opt4', label: 'Minimalist', initialVotes: 6 }
  ];

  var votes = {};
  var selectedId = null;

  var optionsEl = document.getElementById('options');
  var resultsEl = document.getElementById('results');
  var resetBtn = document.getElementById('reset-btn');
  var questionEl = document.getElementById('poll-question');

  questionEl.textContent = QUESTION;

  function initVotes() {
    votes = {};
    OPTIONS.forEach(function (opt) {
      votes[opt.id] = opt.initialVotes;
    });
  }

  function totalVotes() {
    return OPTIONS.reduce(function (sum, opt) {
      return sum + votes[opt.id];
    }, 0);
  }

  function getPercent(id) {
    var total = totalVotes();
    if (total === 0) return 0;
    return Math.round((votes[id] / total) * 100);
  }

  function renderOptions() {
    optionsEl.innerHTML = '';
    OPTIONS.forEach(function (opt) {
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'option-btn';
      btn.setAttribute('aria-pressed', String(selectedId === opt.id));
      btn.setAttribute('aria-label', opt.label + ', ' + votes[opt.id] + ' votes');
      btn.dataset.id = opt.id;

      var label = document.createElement('span');
      label.className = 'option-label';
      label.textContent = opt.label;

      var count = document.createElement('span');
      count.className = 'option-count';
      count.textContent = votes[opt.id] + (votes[opt.id] === 1 ? ' vote' : ' votes');

      btn.appendChild(label);
      btn.appendChild(count);
      btn.addEventListener('click', function () {
        handleVote(opt.id);
      });

      optionsEl.appendChild(btn);
    });
  }

  function renderResults() {
    resultsEl.innerHTML = '';
    OPTIONS.forEach(function (opt) {
      var pct = getPercent(opt.id);

      var row = document.createElement('div');
      row.className = 'result-row';

      var header = document.createElement('div');
      header.className = 'result-header';

      var label = document.createElement('span');
      label.className = 'result-label';
      label.textContent = opt.label;

      var pctEl = document.createElement('span');
      pctEl.className = 'result-pct';
      pctEl.textContent = pct + '%';

      header.appendChild(label);
      header.appendChild(pctEl);

      var track = document.createElement('div');
      track.className = 'bar-track';
      track.setAttribute('role', 'progressbar');
      track.setAttribute('aria-valuenow', String(pct));
      track.setAttribute('aria-valuemin', '0');
      track.setAttribute('aria-valuemax', '100');
      track.setAttribute('aria-label', opt.label + ' percentage');

      var fill = document.createElement('div');
      fill.className = 'bar-fill';
      fill.style.width = pct + '%';

      track.appendChild(fill);
      row.appendChild(header);
      row.appendChild(track);
      resultsEl.appendChild(row);
    });
  }

  function handleVote(id) {
    if (selectedId === id) return;
    if (selectedId !== null) {
      votes[selectedId] = Math.max(0, votes[selectedId] - 1);
    }
    votes[id] += 1;
    selectedId = id;
    renderOptions();
    renderResults();
  }

  function handleReset() {
    initVotes();
    selectedId = null;
    renderOptions();
    renderResults();
  }

  resetBtn.addEventListener('click', handleReset);

  initVotes();
  renderOptions();
  renderResults();
})();
